mapper.select:
SELECT mn.*,
(select count(*) from fund_application_detail d where d.fund_application_id = mn.id) as totalNum,
(select IFNULL(SUM(general_budget), 0) from project_application pa left join fund_application_detail fad on pa.id = fad.project_application_id  where fad.fund_application_id = mn.id) as totalBudget
FROM fund_application mn

    
        and mn.file_name like concat('%',#{fileName},'%')
    
    
        and mn.batch_num like concat('%',#{batchNum},'%')
    
    
        and mn.approve_status=#{approveStatus}
    
    
        and mn.plan_year=#{planYear}
    
    
        and ( mn.create_id= #{createId}
        or mn.id in (select distinct tp_entityid from sys_task_processin where tp_user=#{createId})
        or mn.id in (select distinct CC_FileID from SYS_CarbonCopy where CC_User=#{createId})
        )
    

order by mn.create_time desc
